func findIndex(_ items: [Int], target: Int) -> Int {
    var low = 0
    var high = items.count - 1
    while low <= high {
        let mid = low + (high - low) / 2
        if items[mid] == target { return mid }
        if items[mid] < target { low = mid + 1 }
        else { high = mid - 1 }
    }
    return -1
}
