func searchBoundary(_ arr: [Int], target: Int) -> Int {
    var low = 0
    var high = arr.count
    while low < high {
        let mid = low + (high - low) / 2
        if arr[mid] < target { low = mid + 1 }
        else { high = mid }
    }
    return low
}
let numbers = [1, 3, 3, 3, 5, 7]
print(searchBoundary(numbers, target: 3))

func binarySearchMissing(_ arr: [Int], target: Int) -> Int {
