    var high = arr.count - 1
    var steps = 0
    while low <= high {
        steps += 1
        let mid = low + (high - low) / 2
        if arr[mid] == target { return steps }
        if arr[mid] < target { low = mid + 1 }
        else { high = mid - 1 }
    }
    return steps
}
