func binarySearchIndex(_ array: [Int], target: Int) -> Int? {
    var low = 0
    var high = array.count - 1
    while low <= high {
        let mid = low + (high - low) / 2
        if array[mid] == target {
            return mid
        } else if array[mid] < target {
            low = mid + 1
        } else {
            high = mid - 1
        }
    }
    return nil
}

let items = [4, 8, 15, 16, 23, 42]
print(binarySearchIndex(items, target: 16) ?? -1)
print(binarySearchIndex(items, target: 99) ?? -1)

func findFirstOccurrence(_ array: [Int], target: Int) -> Int? {
    var low = 0
    var high = array.count - 1
    var result: Int? = nil
    while low <= high {
        let mid = low + (high - low) / 2
        if array[mid] == target {
            result = mid
            high = mid - 1
        } else if array[mid] < target {
            low = mid + 1
        } else {
            high = mid - 1
        }
    }
    return result
}

let numbers = [1, 2, 4, 4, 4, 5, 9]
print(findFirstOccurrence(numbers, target: 4) ?? -1)
print(findFirstOccurrence(numbers, target: 7) ?? -1)

func sortPeople(_ people: [(name: String, age: Int)]) -> [(name: String, age: Int)] {
    return people.sorted { first, second in
        if first.age != second.age {
            return first.age < second.age
        }
        return first.name < second.name
    }
}

let people = [(name: "John", age: 30), (name: "Alice", age: 25), (name: "Bob", age: 25)]
let sorted = sortPeople(people)
for person in sorted {
    print("\(person.name): \(person.age)")
}
